function validateSave(s){if(s?.version!==1||!Array.isArray(s.players)||s.players.length<2||s.players.length>4||!Array.isArray(s.props)||s.props.length!==40||!Number.isInteger(s.turn)||s.turn<0||s.turn>=s.players.length||!['roll','end','buy','auction','buildingClaims','card','debt','transfer','won'].includes(s.phase)||!Array.isArray(s.queue)||!s.decks||!Array.isArray(s.log))throw Error('This is not a valid Yerevan Monopoly save.');for(const [i,p] of s.players.entries())if(p.id!==i||typeof p.name!=='string'||!Number.isFinite(p.cash)||p.cash<0||!Number.isInteger(p.pos)||p.pos<0||p.pos>39||!Array.isArray(p.cards))throw Error('Invalid player data.');for(const p of s.props)if(!(p.owner===null||Number.isInteger(p.owner)&&p.owner>=0&&p.owner<s.players.length)||!Number.isInteger(p.houses)||p.houses<0||p.houses>5)throw Error('Invalid property data.');for(const d of ['chance','chest'])if(!Array.isArray(s.decks[d])||s.decks[d].some(i=>!Number.isInteger(i)||i<0||i>15))throw Error('Invalid card deck.');if(s.phase==='auction'&&!s.auction||s.phase==='debt'&&!s.debt||s.phase==='card'&&!s.pendingCard||s.phase==='transfer'&&!s.transfer)throw Error('Missing action data.');}
