function networkActor(){const s=game.s;return s.phase==='auction'?s.auction.bidder:s.phase==='debt'?s.debt.from:s.phase==='transfer'?s.transfer.owner:s.turn;}
function networkGuard(){
 if(!online)return;const r=online.room;if(!r)return;const mine=r.seat===networkActor(),blocked=presenting||networkStatus==='reconnecting'||online.pending||!!online.uncertain||!!r.tradeWaiting;
 ['build','sell-building','mortgage','liquidate-set','confirm-liquidate'].forEach(id=>{const el=$(id);if(!el)return;if(blocked){if(!el.dataset.networkDisabled)el.dataset.baseDisabled=el.disabled?'1':'0';el.dataset.networkDisabled='1';el.disabled=true;}else if(el.dataset.networkDisabled){el.disabled=el.dataset.baseDisabled==='1';delete el.dataset.networkDisabled;}});
 ['roll-dice','end-turn','pay-jail','use-jail-card','quick-buy','quick-auction','buy-deed','auction-deed','resolve-card','place-bid','pass-bid','settle-debt','bankrupt','confirm-bankrupt','transfer-keep','transfer-redeem'].forEach(id=>{const el=$(id);if(!el)return;if(!mine||blocked){if(!el.dataset.networkDisabled){el.dataset.baseDisabled=el.disabled?'1':'0';el.dataset.baseTitle=el.title||'';}el.dataset.networkDisabled='1';el.disabled=true;el.title=blocked?'Waiting for connection or a pending action.':'This action belongs to another player.';}else if(el.dataset.networkDisabled){el.disabled=el.dataset.baseDisabled==='1';el.title=el.dataset.baseTitle||'';delete el.dataset.networkDisabled;}});
 if($('trade-btn'))$('trade-btn').disabled=blocked||!started||!game.canManage(r.seat);if($('round'))$('round').textContent=`ROOM ${r.code} · ${started?'ROUND '+game.s.round:'LOBBY'}`;
 const mode=$('play-mode');if(mode)mode.textContent='ONLINE TABLE';const status=$('network-status');if(status){status.hidden=false;status.classList.toggle('connection-lost',networkStatus==='reconnecting');status.innerHTML=`<div class="network-top"><span class="status-dot"></span><strong>${esc(r.players[r.seat]?.name||'Your seat')}</strong><span>${networkStatus==='reconnecting'?'Connection interrupted':online.pending?'Confirming action…':online.uncertain?'Checking last action…':started?(mine?'Your action':'Watching '+esc(game.s.players[networkActor()]?.name||'')):'Waiting for players'}</span></div><div class="network-bottom"><button id="room-details" class="text-button">Room ${r.code}</button><span>${online.lastSync?'Synced '+activityTime(online.lastSync):'Connecting'}</span></div>${networkStatus==='reconnecting'||online.uncertain?`<p>${esc(networkMessage||'Your confirmed game is saved. Reconnecting automatically…')}</p><button id="retry-room" class="secondary">Reconnect now</button>`:''}`;on('room-details',showOnlineMenu);on('retry-room',async()=>{const button=$('retry-room');if(button)button.disabled=true;try{await online.refresh();}catch(e){toast(e.message);}finally{networkGuard();}});}
 $('save-label').textContent=networkStatus==='reconnecting'?'Connection interrupted · Game saved':online.uncertain?'Confirming last action…':'Online · Saved to room';$('tab-chat').hidden=false;renderVoice();

}
function makeRoomClient(){chatSeen=new Set();chatLoaded=false;chatUnread=0;chatSignature='';const client=new RoomClient(receiveRoom,(status,message)=>{networkStatus=status;networkMessage=message||'';networkGuard();updateUndo();},receiveSocial);voice=new RoomVoice(client,renderVoice,levels=>{document.querySelectorAll('[data-voice-seat]').forEach(el=>el.classList.toggle('speaking',!!levels[Number(el.dataset.voiceSeat)]));});return client;}
function receiveRoom(room,previous){
 if(!online||online.room?.code!==room.code)return;if(!room.state){showRoomLobby();networkGuard();return;}
 if(previous?.state&&room.state.presentation?.id===previous.state.presentation?.id&&room.state.phase===previous.state.phase&&room.tradeWaiting===previous.tradeWaiting&&JSON.stringify(room.claimsSubmitted)===JSON.stringify(previous.claimsSubmitted)){networkGuard();return;}const old=game?.s;if(!presenting)motionPrevious=previous?.state??null;game=new Game([],Math.random,room.state);started=true;const snap=!previous?.state||room.state.presentation?.action==='undo';if(snap)resetPresentation();else if(room.state.presentation?.action==='roll'&&old?.presentation?.id!==room.state.presentation.id&&!(onlineRollPending&&room.seat===old?.turn))view?.roll();render();
 finishPresentation(()=>{showPhase();if(previous?.state)room.state.props.forEach((p,i)=>{if(p.owner!==null&&previous.state.props[i].owner!==p.owner&&room.state.presentation?.action!=='undo')purchaseNotice(i,room.state.players[p.owner],BOARD[i].price);});networkGuard();});

}
function showOnlineSetup(prefill=''){
 if(typeof prefill!=='string')prefill='';
 if(location.protocol==='file:'){modal(`<span class="eyebrow">ONLINE MULTIPLAYER</span><h2>Open the web version.</h2><p>The downloaded game supports one-computer play. For separate computers, open the online game and create a room.</p><a class="primary dark" href="https://example.invalid/" target="_blank" rel="noopener">Open online game</a><button class="text-button" id="offline-back">Back to local play</button>`,'online');on('offline-back',showSetup);return;}
 let seats=[];try{seats=JSON.parse(localStorage.getItem('yerevan-online-seats')||'[]');}catch{}
 modal(`<span class="eyebrow">PLAY TOGETHER · SEPARATE SCREENS</span><h2>Your friends. One table.</h2><p>2–4 players can join from different computers. Everyone uses their own browser. No account is required.</p><label for="online-name">Your name</label><input id="online-name" maxlength="22" value="${esc(seats.at(-1)?.name||'')}" placeholder="Your name" autocomplete="nickname"><div class="online-options"><section><h3>Create a room</h3><label for="room-capacity">Maximum players</label><select id="room-capacity"><option value="2">2 players</option><option value="3">3 players</option><option value="4" selected>4 players</option></select><button class="primary dark" id="create-room">Create room</button></section><section><h3>Join friends</h3><label for="room-code">Room code</label><input id="room-code" maxlength="8" value="${esc(prefill)}" placeholder="8-character code" autocomplete="off" autocapitalize="characters"><button class="secondary" id="join-room">Join room</button></section></div><p id="online-error" role="alert" class="online-error"></p>${seats.length?`<details class="rejoin-list"><summary>Rejoin a saved seat</summary>${seats.slice().reverse().map((r,i)=>`<button class="secondary" data-rejoin="${i}">${esc(r.name)} · ${esc(r.code)}</button>`).join('')}</details>`:''}<button class="text-button" id="local-play">Play on one computer instead</button><p class="setup-foot">Your seat is remembered on this browser. Rooms expire after seven inactive days. Share the room code only with your players.</p>`,'online-setup',true,started);
 const run=async fn=>{for(const id of ['create-room','join-room'])$(id).disabled=true;$('online-error').textContent='Connecting…';try{online=makeRoomClient();await fn();}catch(e){online?.leave();online=null;if($('online-error'))$('online-error').textContent=e.message;for(const id of ['create-room','join-room'])if($(id))$(id).disabled=false;}};
 on('create-room',()=>run(()=>online.create($('online-name').value.trim(),Number($('room-capacity').value))));on('join-room',()=>run(()=>online.join($('room-code').value.trim().toUpperCase(),$('online-name').value.trim())));on('local-play',()=>{history.replaceState(null,'',location.pathname);showSetup();});$('modal').querySelectorAll('[data-rejoin]').forEach(el=>el.onclick=()=>run(()=>online.reconnect(seats.slice().reverse()[Number(el.dataset.rejoin)])));
}
function showRoomLobby(){
 if(!online?.room)return;const r=online.room;started=false;const link=location.origin+'/?room='+r.code;
 modal(`<span class="eyebrow">ONLINE ROOM · ${esc(r.code)}</span><h2>Gather your table.</h2><p>Invite friends with this link or room code. The host starts when at least two players have joined.</p><div class="room-code-display">${esc(r.code)}</div><button class="secondary" id="copy-room">Copy invite link</button><p class="invite-url">${esc(link)}</p><div class="lobby-seats">${Array.from({length:r.capacity},(_,i)=>`<div><span class="token" style="--c:${TOKENS[i].color}">${tokenArt(i)}</span><strong>${r.players[i]?esc(r.players[i].name):'Open seat'}</strong><small>${i===r.seat?'YOU':i===0?'HOST':r.players[i]?'JOINED':'WAITING'}</small></div>`).join('')}</div><p id="lobby-error" role="alert" class="online-error"></p>${r.seat===0?`<button class="primary dark" id="start-online" ${r.players.length<2?'disabled':''}>Start game · ${r.players.length} players</button>`:'<p class="waiting-note">Waiting for the host to start…</p>'}<button class="text-button" id="leave-room">Back to local play</button><p class="setup-foot">Refresh or reopen this website in the same browser to reconnect. Once started, seats are locked and a disconnected player keeps their seat.</p>`,'lobby',false,false);
 on('copy-room',async()=>{try{await navigator.clipboard.writeText(link);toast('Invite link copied.');}catch{toast('Room code: '+r.code);}});on('start-online',async()=>{try{await online.send('start');}catch(e){if($('lobby-error'))$('lobby-error').textContent=e.message;else toast(e.message);}});on('leave-room',leaveNetwork);
}
function showOnlineMenu(){const r=online.room;modal(`<span class="eyebrow">YOUR ONLINE TABLE</span><h2>Room ${esc(r.code)}</h2><p>You are ${esc(r.players[r.seat].name)}. The game saves after every confirmed action. Refreshing reconnects your seat; other players cannot move for you.</p><p>${r.players.map(p=>esc(p.name)).join(' · ')}</p>${r.tradeWaiting?'<button class="secondary" id="review-online-trade">Review pending trade</button>':''}<button class="secondary" id="online-rules">How to play</button><button class="primary dark" id="online-return">Back to the table</button><button class="text-button" id="online-leave">Leave screen · keep my seat</button>`,'online-menu');on('online-return',()=>{if(r.state)closeModal();else showRoomLobby();});on('online-rules',showRules);on('online-leave',leaveNetwork);on('review-online-trade',showOnlineTrade);}
function leaveNetwork(){voice?.leave();voice=null;$('voice-panel').hidden=true;$('tab-chat').hidden=true;selectTray('players');online?.leave();online=null;networkStatus='connected';started=false;history.replaceState(null,'',location.pathname);$('network-status').hidden=true;$('save-label').textContent='Auto-save on';if($('play-mode'))$('play-mode').textContent='PASS & PLAY';game=new Game(['Player 1','Player 2']);undoHistory=[];resetPresentation();render();showSetup();}
async function bootNetwork(){const code=new URLSearchParams(location.search).get('room')?.toUpperCase();let session=null;try{session=JSON.parse(sessionStorage.getItem('yerevan-online-seat')||'null');}catch{}if(location.protocol!=='file:'&&session&&(!code||code===session.code)){online=makeRoomClient();try{await online.reconnect(session);return;}catch(e){if(!e.status||e.status>=500){modal(`<span class="eyebrow">YOUR SEAT IS SAVED</span><h2>Reconnecting to your table.</h2><p>Your room and player seat are still saved. We’ll restore the latest board as soon as the connection returns.</p><p id="restore-error" role="status">${esc(e.message)}</p><button class="primary dark" id="retry-saved-room">Reconnect now</button><button class="text-button" id="leave-restore">Back to local play</button>`,'reconnecting',false,false);online.poll();on('retry-saved-room',async()=>{try{await online.refresh();}catch(error){if($('restore-error'))$('restore-error').textContent=error.message;}});on('leave-restore',leaveNetwork);return;}online.leave();online=null;}}if(code)showOnlineSetup(code);else showSetup();}
async function sendOnlineTrade(d){try{await online.send('proposeTrade',{args:[d.a,d.b,d.A,d.B,d.cashA,d.cashB,d.cardsA,d.cardsB,d.redeem]});toast('Proposal sent. Waiting for the other player.');showOnlineTrade();}catch(e){toast(e.message);}}
function showOnlineTrade(){const r=online.room,t=r.pendingTrade;if(!t){modal('<h2>Trade in progress.</h2><p>Two players are reviewing a proposal. The table resumes when they accept or decline.</p><button class="primary dark" id="trade-wait-close">Review board</button>','online-trade');on('trade-wait-close',closeModal);return;}const [a,b,A,B,cashA,cashB,cardsA,cardsB,redeem]=t.args,recipient=r.seat===b,summary=(id,deeds,cash,cards)=>`<div class="trade-col"><strong>${esc(game.s.players[id].name)} gives</strong><p>${deeds.map(i=>esc(BOARD[i].name)).join(', ')||'No deeds'}</p><p>${money(cash)} · ${cards} jail cards</p></div>`;modal(`<span class="eyebrow">BOTH PLAYERS MUST AGREE</span><h2>${recipient?'Review the proposal.':'Waiting for acceptance.'}</h2><div class="trade-grid">${summary(a,A,cashA,cardsA)}${summary(b,B,cashB,cardsB)}</div><p>${redeem.length?'Redeem immediately: '+redeem.map(i=>esc(BOARD[i].name)).join(', ')+'. ':''}Recipients pay mortgage interest or redemption costs. The table is paused while this proposal is pending.</p>${recipient?'<button class="primary dark" id="online-accept-trade">Accept trade</button>':''}<button class="secondary" id="online-decline-trade">${recipient?'Decline trade':'Cancel proposal'}</button><button class="text-button" id="online-trade-board">Review board</button>`,'online-trade');const respond=async accept=>{try{await online.send('respondTrade',{tradeId:t.id,accept});toast(accept?'Trade complete.':'Proposal closed.');}catch(e){toast(e.message);}};on('online-accept-trade',()=>respond(true));on('online-decline-trade',()=>respond(false));on('online-trade-board',closeModal);}
function showOnlineClaims(){const r=online.room,b=game.s.buildRequest,c=b.candidates.find(x=>x.id===r.seat),done=r.claimsSubmitted.includes(r.seat);modal(`<span class="eyebrow">A BUILDING SHORTAGE</span><h2>The last ${b.kind}.</h2><p>Each eligible player chooses a placement or passes. The building is auctioned if multiple players claim it.</p>${b.candidates.map(x=>`<p>${esc(game.s.players[x.id].name)} · ${r.claimsSubmitted.includes(x.id)?'Submitted':'Waiting'}</p>`).join('')}${c&&!done?`<label for="online-claim">Your placement</label><select id="online-claim"><option value="">No claim</option>${c.deeds.map(i=>`<option value="${i}">${esc(BOARD[i].name)}</option>`).join('')}</select><button class="primary dark" id="submit-online-claim">Submit my choice</button>`:'<p>Waiting for the other eligible players…</p>'}<button class="text-button" id="claims-board">Review board</button>`,'online-claims');on('claims-board',closeModal);on('submit-online-claim',()=>{const v=$('online-claim').value;perform(()=>game.buildingClaims(v===''?{}:{[r.seat]:Number(v)}));});}

function selectTray(tab){trayTab=tab;for(const [id,name] of [['roster','players'],['journal','history'],['room-chat','chat']]){$(id).hidden=tab!==name;if(id==='roster')$(id).style.display=tab==='players'?'':'none';}for(const [id,name] of [['tab-players','players'],['tab-log','history'],['tab-chat','chat']]){$(id).classList.toggle('active',tab===name);$(id).setAttribute('aria-pressed',String(tab===name));}if(tab==='history')renderHistory();if(tab==='chat'){chatUnread=0;updateChatBadge();renderChat(true);}}
function renderHistory(){const state=game.s,filter=$('history-player'),names=state.players.map(p=>p.name).join('|');if(filter.dataset.names!==names){filter.innerHTML='<option value="all">All players</option>'+state.players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');filter.dataset.names=names;filter.value=historyFilter;}const groups=activityGroups(state,historyFilter),signature=JSON.stringify(groups);if(historySignature===signature)return;historySignature=signature;const list=$('activity-list'),scroll=list.scrollTop;list.innerHTML=groups.length?groups.map(g=>{const p=state.players[g.player],events=[...g.events].reverse(),balances=new Map();g.events.forEach(e=>{if(e.balance!==undefined&&!balances.has(e.player))balances.set(e.player,e.balance);});return `<article class="activity-card" style="--activity-color:${p?TOKENS[p.id].color:'#aa9773'}"><div class="activity-avatar">${p?tokenArt(p.id):icon('dice')}</div><div class="activity-content"><div class="activity-meta"><strong>${p?esc(p.name):'The table'}</strong>${g.round?`<span>ROUND ${g.round}</span>`:''}<time ${g.at?`datetime="${new Date(g.at).toISOString()}" title="${esc(new Date(g.at).toLocaleString())}"`:''}>${activityTime(g.at)}</time></div><h3>${esc(activityTitle(g))}</h3><ul>${events.map(e=>`<li class="activity-${esc(e.type||'event')}">${esc(e.text)}</li>`).join('')}</ul>${balances.size?`<div class="activity-balances">${[...balances].map(([id,n])=>`<span>${esc(state.players[id]?.name||'Player')} cash <b>${money(n)}</b></span>`).join('')}</div>`:''}</div></article>`;}).join(''):'<p class="social-empty">Moves will appear here as the game progresses.</p>';list.scrollTop=scroll;}
function receiveSocial(data){if(!online)return;const initial=!chatLoaded;chatLoaded=true;for(const m of data.messages||[]){if(!chatSeen.has(m.id)&&!initial&&m.seat!==online.room.seat&&trayTab!=='chat')chatUnread++;chatSeen.add(m.id);}voice?.applyMembers(data.voiceMembers);renderChat();updateChatBadge();}
function updateChatBadge(){const badge=$('chat-unread');badge.hidden=!chatUnread;badge.textContent=chatUnread>99?'99+':String(chatUnread);}
function renderChat(force=false){const list=$('chat-messages'),messages=online?.socialData?.messages||[],signature=JSON.stringify(messages);if(!force&&signature===chatSignature)return;chatSignature=signature;const atBottom=list.scrollHeight-list.scrollTop-list.clientHeight<60,scroll=list.scrollTop;list.innerHTML=messages.length?messages.map(m=>{const p=online.room.players[m.seat],mine=m.seat===online.room.seat;return `<article class="chat-message ${mine?'mine':''}" style="--message-color:${TOKENS[m.seat]?.color||'#a9bb9d'}"><span class="chat-avatar">${tokenArt(m.seat)}</span><div><header><strong>${esc(p?.name||'Player')}${mine?' <small>YOU</small>':''}</strong><time datetime="${new Date(m.at).toISOString()}" title="${esc(new Date(m.at).toLocaleString())}">${activityTime(m.at)}</time></header><p dir="auto">${esc(m.text)}</p></div></article>`;}).join(''):'<div class="social-empty"><strong>The conversation starts here.</strong><span>Say hello or discuss your next trade.</span></div>';if(force||atBottom)list.scrollTop=list.scrollHeight;else list.scrollTop=scroll;}
async function sendChat(event){event.preventDefault();if(!online||chatSending)return;const input=$('chat-input'),text=input.value.trim();if(!text)return;chatSending=true;$('chat-send').disabled=true;$('chat-feedback').textContent='Sending…';try{await online.chat(text);if(input.value.trim()===text)input.value='';$('chat-feedback').textContent='';renderChat(true);}catch(e){$('chat-feedback').textContent=e.message;}finally{chatSending=false;$('chat-send').disabled=false;input.focus();}}
function renderVoice(){const panel=$('voice-panel');if(!voice||!online?.room){panel.hidden=true;return;}panel.hidden=false;const v=voice.snapshot(),r=online.room;const signature=JSON.stringify(v)+r.players.map(p=>p.name).join('|');if(panel.dataset.signature===signature)return;panel.dataset.signature=signature;const members=v.members||[],connected=v.peers.filter(p=>p.state==='connected').length;panel.innerHTML=`<div class="voice-heading"><span class="voice-symbol">${icon('voice')}</span><div><strong>Table voice</strong><small>${v.joining?'Waiting for microphone…':v.active?connected?'Connected · '+(connected+1)+' players':'You’re in · waiting for others':'Optional · microphone off'}</small></div><span class="voice-count">${members.length} / ${r.players.length}</span></div>${members.length?`<div class="voice-members">${members.map(m=>{const peer=v.peers.find(p=>p.seat===m.seat),own=m.seat===r.seat,label=m.muted?'Muted':own&&v.active?'Microphone on':peer?.state==='connected'?'Connected':v.active?'Connecting…':'In voice';return `<span class="voice-member" data-voice-seat="${m.seat}" style="--voice-color:${TOKENS[m.seat].color}" title="${esc(r.players[m.seat]?.name)} · ${label}"><i>${tokenArt(m.seat)}</i><span>${esc(r.players[m.seat]?.name)}<small>${label}</small></span></span>`;}).join('')}</div>`:''}<div class="voice-controls">${v.active?`<button id="voice-mute" class="${v.muted?'muted':''}" aria-pressed="${v.muted}">${v.muted?'Unmute mic':'Mute mic'}</button><button id="voice-deafen" aria-pressed="${v.deafened}">${v.deafened?'Hear table':'Deafen'}</button><button id="voice-leave">Leave</button>`:`<button id="voice-join" ${v.joining?'disabled':''}>${v.joining?'Connecting…':'Join voice'}</button>`}</div>${v.error?`<p class="voice-error" role="status">${esc(v.error)}</p>${v.error.includes('Enable audio')?'<button id="voice-enable-audio">Enable audio</button>':''}`:''}${!v.active&&!v.joining?'<p class="voice-privacy">Microphone starts only when you join. Audio is not recorded.</p>':''}`;on('voice-join',()=>voice.join());on('voice-mute',()=>voice.toggleMute());on('voice-deafen',()=>voice.toggleDeafen());on('voice-leave',()=>voice.leave());on('voice-enable-audio',()=>voice.enableAudio());}
window.addEventListener('pagehide',()=>{voice?.stream?.getTracks().forEach(t=>t.stop());});
